import{_ as o,o as e,c as a,a5 as r}from"./chunks/framework.D47SInms.js";const n="/RBQ/nightly/images/app/settings-pwr.pc.ko.png",u=JSON.parse('{"title":"외부 포트 전원 켜기","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/interface/port-power.md","filePath":"ko/manual/interface/port-power.md","lastUpdated":1791600043000}'),d={name:"ko/manual/interface/port-power.md"};function l(s,t,i,c,h,p){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="외부-포트-전원-켜기" tabindex="-1">외부 포트 전원 켜기 <a class="header-anchor" href="#외부-포트-전원-켜기" aria-label="Permalink to &quot;외부 포트 전원 켜기&quot;">​</a></h1><p>페이로드를 외부 포트에 물렸는데 아무 반응이 없다면, 대개 <strong>그 포트로 나가는 전원이 꺼져 있는</strong> 것입니다. 포트의 전원은 커넥터를 꽂는 것만으로 살아나지 않고 <strong>앱에서 켜야</strong> 합니다.</p><p>배선과 핀 배열은 <a href="/RBQ/nightly/ko/manual/interface/external-port.html">외부 포트 정보</a>에, 케이블은 <a href="/RBQ/nightly/ko/manual/product-descriptions/accessories.html#payload-cabling">액세서리</a>에 있습니다.</p><h2 id="where" tabindex="-1">어디에서 켜나 <a class="header-anchor" href="#where" aria-label="Permalink to &quot;어디에서 켜나 {#where}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>화면</th><th>접근</th><th>여기 있는 것</th></tr></thead><tbody><tr><td><strong>설정 → 전원 제어</strong></td><td>모든 사용자</td><td>일상 운용에서 켜고 끄는 보조 전원</td></tr><tr><td><strong>정비 → 전원 / 시스템</strong></td><td><a href="/RBQ/nightly/ko/manual/gui/developer-mode.html">개발자 모드</a>(레벨 2 이상)</td><td>위 전부 + 끄면 연결·자세가 끊기는 레일</td></tr></tbody></table><p>일반적인 페이로드는 <strong>설정 → 전원 제어</strong>만으로 충분합니다.</p><p><img src="'+n+'" alt="설정 → 전원 제어"></p><h2 id="48v" tabindex="-1">48V 포트 켜기 <a class="header-anchor" href="#48v" aria-label="Permalink to &quot;48V 포트 켜기 {#48v}&quot;">​</a></h2><p><code>POWER</code>(2핀)와 <code>PWR-CAN</code>(4핀)처럼 배터리 전압을 그대로 쓰는 포트는 48V 레일에 물려 있습니다.</p><ol><li><strong>설정 → 전원 제어</strong>를 엽니다.</li><li><code>EXTERN (48V)</code> 행의 <strong><code>켜기</code></strong> 를 누릅니다. 외부 확장 포트로 나가는 전원입니다.</li><li>확인 창 <code>정말 켤까요?</code>에서 <strong><code>켜기</code></strong> 로 확정합니다.</li><li>같은 행에 표시되는 <strong>현재 전압</strong>이 올라오는지 확인합니다.</li></ol><p>애드온 장치가 <code>ARM · ADDON (48V)</code> 쪽이라면 그 행을 켭니다.</p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p><code>ARM · ADDON (48V)</code> 는 팔과 애드온이 <strong>PDU 포트 하나를 함께</strong> 씁니다. 이 레일을 끄면 팔 전원도 같이 나가므로, 끄기 전에 팔이 정지 상태인지 확인하세요.</p></div></div><p>48V 계열이 내보내는 전압은 <strong>배터리 전압 그대로</strong>라 잔량에 따라 42.0~58.4 V 사이에서 변합니다. 정전압이 필요한 페이로드에는 컨버터를 따로 두세요.</p><h2 id="12v" tabindex="-1">12V 장치 켜기 <a class="header-anchor" href="#12v" aria-label="Permalink to &quot;12V 장치 켜기 {#12v}&quot;">​</a></h2><p>카메라·조명처럼 12V로 도는 장치는 장치별 토글을 한 번 탭해 켭니다.</p><table tabindex="0"><thead><tr><th>토글</th><th>무엇의 전원인가</th></tr></thead><tbody><tr><td><code>스피커 앰프 (12V)</code></td><td>워키토키 소리 출력 — 꺼져 있으면 무음</td></tr><tr><td><code>CCTV (12V)</code></td><td>PTZ 유닛의 컬러 카메라</td></tr><tr><td><code>열화상 (12V)</code></td><td>PTZ 유닛의 열화상 카메라</td></tr><tr><td><code>IR LED (12V)</code></td><td>야간 조명</td></tr></tbody></table><p><code>LiDAR (12V)</code>, <code>카메라 (5V)</code>, <code>오디오·USB 허브 (5V)</code>, <code>Vision PC (12V)</code>, <code>통신 (12V)</code>은 끄면 주행·영상·연결이 끊기므로 <strong>정비 → 전원 / 시스템</strong>(<a href="/RBQ/nightly/ko/manual/gui/developer-mode.html">개발자 모드</a>)에 있습니다.</p><h2 id="not-working" tabindex="-1">켰는데도 안 될 때 <a class="header-anchor" href="#not-working" aria-label="Permalink to &quot;켰는데도 안 될 때 {#not-working}&quot;">​</a></h2><ul><li><strong>토글이 회색이고 눌리지 않습니다</strong> — 레일 상태를 아직 못 받은 것입니다. 로봇 연결을 먼저 확인하세요(<a href="/RBQ/nightly/ko/manual/gui/connection.html">연결</a>).</li><li><strong>켰는데 바로 안 바뀝니다</strong> — 토글은 로봇 PDU가 보고한 <strong>실제 상태</strong>를 표시합니다. 반영에 1초 정도 걸립니다.</li><li><strong>전압이 올라오지 않습니다</strong> — 커넥터 체결과 케이블을 확인하세요 (<a href="/RBQ/nightly/ko/manual/maintenance/connector.html">커넥터 탈부착</a>).</li><li><strong>전원은 들어오는데 장치가 안 켜집니다</strong> — 포트별 최대 전류를 넘지 않는지 확인하세요: <code>POWER</code> 5 A · <code>PWR-CAN</code> 10 A · <code>12V/LAN</code> 2~3 A (<a href="/RBQ/nightly/ko/manual/interface/external-port.html#user-port-pin-map">핀맵</a>).</li></ul><h2 id="still-stuck" tabindex="-1">그래도 해결되지 않으면 <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;그래도 해결되지 않으면 {#still-stuck}&quot;">​</a></h2><p>어느 포트에 무엇을 물렸는지, 그리고 전원 화면에 표시된 전압을 함께 알려주시면 확인이 빠릅니다.</p><p><strong>→ <a href="/RBQ/nightly/ko/manual/support/">기술지원 요청</a></strong></p>',22)])])}const m=o(d,[["render",l]]);export{u as __pageData,m as default};
